  expectations.push(...row.semantic_effects.map((item) => `\u7ED3\u679C\u53D8\u5316\uFF1A${item.subject}\uFF1A${Object.hasOwn(item, "before") ? `${item.before} \u2192 ` : ""}${item.after}`));
