  const baseline = row.baseline ? `<section><h4>\u76F8\u5BF9\u57FA\u7EBF</h4><p>${html(row.baseline.reference)}\uFF1B${html(baselineComparison(row.baseline.comparison_contract))}</p></section>` : "";
